<div class="analysis-grid"><section class="card"><div class="section-title"><h2>软件版本观察</h2></div><div class="table-scroll"><table><thead><tr><th>版本</th><th>设备</th><th>异常事件</th><th>全部事件</th></tr></thead><tbody><?php foreach($byVersion as $v): ?><tr><td><a href="<?= e(lc_diag_url('/admin/events',['version'=>$v['version']])) ?>"><?= e($v['version'] ?: '未上报版本') ?></a></td><td><?= (int)$v['devices'] ?></td><td><?= (int)$v['errors'] ?></td><td><?= (int)$v['events'] ?></td></tr><?php endforeach; ?><?php if(!$byVersion): ?><tr><td colspan="4" class="empty">暂无版本数据。</td></tr><?php endif; ?></tbody></table></div></section>
